import type { Page, Response } from "../../../sdk/index.ts";
import { MangaThemesia } from "../../../themes/mangathemesia/index.ts";

const JETPACK_PROXY = /^https?:\/\/i\d\.wp\.com\//;

export default class MangaTrend extends MangaThemesia {
  // Not upstream: the site serves its pages through Jetpack's image proxy (i0.wp.com), which answers 400/504 for
  // the largest files (10+ MB PNGs); fall back to the origin, which the proxy URL embeds.
  override async getImage(page: Page): Promise<Response> {
    const response = await super.getImage(page);
    if (response.isSuccessful || !JETPACK_PROXY.test(page.imageUrl ?? "")) return response;
    const { headers } = this.imageRequest(page);
    return this.client.execute({ url: page.imageUrl!.replace(JETPACK_PROXY, "https://").replace(/\?.*$/, ""), method: "GET", headers });
  }
}
